-- Module 4: Fechas y Tiempo lessons
  "intro": "Los días de la semana son esenciales en inglés. Siempre se escriben con mayúscula y sus nombres tienen origen en la mitología nórdica y romana.",
  "sections": [
    {"type": "table", "title": "LOS 7 DÍAS", "headers": ["Inglés", "Español", "Pronunciación"], "rows": [["Monday","lunes","/ˈmʌndeɪ/"],["Tuesday","martes","/ˈtjuːzdeɪ/"],["Wednesday","miércoles","/ˈwɛnzdeɪ/"],["Thursday","jueves","/ˈθɜːrzdeɪ/"],["Friday","viernes","/ˈfraɪdeɪ/"],["Saturday","sábado","/ˈsætərdeɪ/"],["Sunday","domingo","/ˈsʌndeɪ/"]]},
    {"type": "explanation", "title": "WEEKDAYS VS WEEKEND", "text": "Los días de lunes a viernes se llaman ''weekdays'' (días laborables). Sábado y domingo forman el ''weekend'' (fin de semana)."},
    {"type": "note", "variant": "warning", "text": "''Wednesday'' se pronuncia /ˈwɛnzdeɪ/ — la ''d'' del medio es silenciosa. La preposición con los días es ''on'': ''on Monday'', ''on Tuesdays'' (habitual)."}
  ]
}'::jsonb, true),
('00000002-0000-0000-0004-000000000002', '00000001-0000-0000-0000-000000000004', '00000000-0000-0000-0001-000000000001', 2, 'meses-ano', '{"es": "Los Meses del Año", "en": "Months of the Year"}'::jsonb, '{"es": "Aprende los doce meses del año en inglés.", "en": "Learn the twelve months of the year in English."}'::jsonb, 'vocabulary', 15, 10, '{
  "intro": "Los doce meses del año en inglés siempre se escriben con mayúscula. Se usan con la preposición ''in'': in January, in March.",
  "sections": [
    {"type": "table", "title": "LOS 12 MESES", "headers": ["Mes", "Inglés", "Abrev."], "rows": [["1","January","Jan."],["2","February","Feb."],["3","March","Mar."],["4","April","Apr."],["5","May","May"],["6","June","Jun."],["7","July","Jul."],["8","August","Aug."],["9","September","Sep."],["10","October","Oct."],["11","November","Nov."],["12","December","Dec."]]},
    {"type": "note", "variant": "info", "text": "En inglés americano las fechas se escriben mes/día/año: 01/15/2025 = January 15, 2025. En inglés británico es día/mes/año: 15/01/2025."}
  ]
}'::jsonb, true),
('00000002-0000-0000-0004-000000000003', '00000001-0000-0000-0000-000000000004', '00000000-0000-0000-0001-000000000001', 3, 'estaciones', '{"es": "Las Estaciones del Año", "en": "Seasons of the Year"}'::jsonb, '{"es": "Aprende las estaciones y vocabulario del clima.", "en": "Learn the seasons and weather vocabulary."}'::jsonb, 'vocabulary', 15, 12, '{
  "intro": "Las cuatro estaciones y el vocabulario del clima son temas de conversación muy comunes en inglés, especialmente en el Reino Unido.",
  "sections": [
    {"type": "table", "title": "LAS ESTACIONES", "headers": ["Inglés", "Español", "Meses"], "rows": [["spring","primavera","March, April, May"],["summer","verano","June, July, August"],["fall / autumn","otoño","September, October, November"],["winter","invierno","December, January, February"]]},
    {"type": "table", "title": "VOCABULARIO DEL CLIMA", "headers": ["Inglés", "Español"], "rows": [["sunny","soleado"],["cloudy","nublado"],["rainy","lluvioso"],["windy","ventoso"],["hot","caliente"],["cold","frío"],["warm","cálido"],["foggy","neblinoso"]]},
    {"type": "note", "variant": "info", "text": "Para hablar del clima: ''It''s sunny'' (está soleado), ''It''s raining'' (está lloviendo), ''It''s cold'' (hace frío). El sujeto impersonal ''it'' no tiene traducción directa al español."}
  ]
}'::jsonb, true),
('00000002-0000-0000-0004-000000000004', '00000001-0000-0000-0000-000000000004', '00000000-0000-0000-0001-000000000001', 4, 'decir-hora', '{"es": "Decir la Hora", "en": "Telling the Time"}'::jsonb, '{"es": "Aprende a decir y preguntar la hora en inglés.", "en": "Learn to tell and ask the time in English."}'::jsonb, 'grammar', 15, 15, '{
  "intro": "Saber decir la hora en inglés es esencial para la vida diaria. Hay dos métodos: el digital (más simple) y el tradicional con ''past'' y ''to''.",
  "sections": [
    {"type": "table", "title": "CÓMO DECIR LA HORA", "headers": ["Hora", "Método tradicional", "Método digital"], "rows": [["3:00","It''s three o''clock","It''s three"],["3:15","It''s quarter past three","It''s three fifteen"],["3:30","It''s half past three","It''s three thirty"],["3:45","It''s quarter to four","It''s three forty-five"],["3:10","It''s ten past three","It''s three ten"]]},
    {"type": "explanation", "title": "AM Y PM", "text": "En inglés se usa el sistema de 12 horas con a.m. (antes del mediodía) y p.m. (después del mediodía). ''Noon'' = mediodía, ''midnight'' = medianoche."},
    {"type": "note", "variant": "tip", "text": "El método digital es más fácil para principiantes. ''It''s three thirty'' es completamente natural. ''O''clock'' solo se usa para horas exactas (sin minutos)."}
  ]
}'::jsonb, true),
('00000002-0000-0000-0004-000000000005', '00000001-0000-0000-0000-000000000004', '00000000-0000-0000-0001-000000000001', 5, 'hablar-fechas', '{"es": "Hablar de Fechas", "en": "Talking About Dates"}'::jsonb, '{"es": "Aprende a expresar y preguntar fechas completas.", "en": "Learn to express and ask about complete dates."}'::jsonb, 'grammar', 15, 12, '{
  "intro": "Hablar de fechas es esencial para hacer citas, planear eventos y hablar de cumpleaños. La preposición correcta es clave.",
  "sections": [
    {"type": "table", "title": "PREPOSICIONES CON TIEMPO", "headers": ["Preposición", "Uso", "Ejemplo"], "rows": [["on","días y fechas específicas","on Monday / on January 15th"],["in","meses, años, estaciones","in January / in 2025 / in spring"],["at","horas específicas","at 3 o''clock / at noon"]]},
    {"type": "examples", "title": "EJEMPLOS DE FECHAS", "items": [{"label": "AMERICANO", "en": "Today is March 21st, 2025.", "es": "Hoy es el 21 de marzo de 2025."},{"label": "PREGUNTA", "en": "What''s the date today? It''s the fifth of June.", "es": "¿Cuál es la fecha hoy? Es el cinco de junio."}]},
    {"type": "note", "variant": "tip", "text": "Regla mnemotécnica AT-ON-IN: AT para horas (at 5 pm), ON para días y fechas (on Monday), IN para periodos más largos (in June, in 2025)."}
  ]
}'::jsonb, true);


