('00000003-0005-0002-0007-000000000001', '00000002-0000-0000-0005-000000000002', 7, 'translation', '{"text": "La mesa es cuadrada."}', '{"text": "The table is square.", "accepted": ["The table is square."]}', null, '{"es": "''Square'' significa cuadrado. La estructura es: sujeto + verbo to be + adjetivo."}'),
