('00000003-0005-0004-0003-000000000001', '00000002-0000-0000-0005-000000000004', 3, 'multiple_choice', '{"text": "¿Qué adjetivo usamos para describir a una mujer bonita?"}', '{"text": "pretty"}', '["handsome", "tall", "young"]', '{"es": "''Pretty'' se usa para describir a una mujer bonita. ''Handsome'' se usa generalmente para los hombres."}'),
('00000003-0005-0004-0004-000000000001', '00000002-0000-0000-0005-000000000004', 4, 'multiple_choice', '{"text": "My teacher is very ___. She always smiles. (simpática)"}', '{"text": "friendly"}', '["serious", "old", "short"]', '{"es": "''Friendly'' significa simpático o amigable. Alguien que siempre sonríe es una persona amigable."}'),
('00000003-0005-0004-0005-000000000001', '00000002-0000-0000-0005-000000000004', 5, 'fill_blank', '{"text": "My grandfather is ___. He is 75 years old. (mayor/viejo)"}', '{"text": "old", "accepted": ["old"]}', null, '{"es": "''Old'' puede significar viejo o mayor. Se usa tanto para objetos como para personas."}'),
('00000003-0005-0004-0006-000000000001', '00000002-0000-0000-0005-000000000004', 6, 'fill_blank', '{"text": "He is ___ . He is 6 feet tall. (alto)"}', '{"text": "tall", "accepted": ["tall"]}', null, '{"es": "''Tall'' significa alto/a y se usa para describir la estatura de las personas o la altura de los edificios."}'),
('00000003-0005-0004-0007-000000000001', '00000002-0000-0000-0005-000000000004', 7, 'translation', '{"text": "Mi amigo es alto y simpático."}', '{"text": "My friend is tall and friendly.", "accepted": ["My friend is tall and friendly."]}', null, '{"es": "''Tall'' es alto y ''friendly'' es simpático. Conectamos los adjetivos con ''and''."}'),
('00000003-0005-0004-0008-000000000001', '00000002-0000-0000-0005-000000000004', 8, 'translation', '{"text": "Ella es joven y muy bonita."}', '{"text": "She is young and very pretty.", "accepted": ["She is young and very pretty.", "She is young and very beautiful."]}', null, '{"es": "''Young'' es joven y ''pretty'' es bonita. También puedes usar ''beautiful'' para bonita."}');



('00000003-0006-0002-0001-000000000001', '00000002-0000-0000-0006-000000000002', 1, 'flashcard', '{"text": "sibling", "subtext": "general term for brother or sister"}', '{"text": "hermano/a (en general)", "phonetic": "/ˈsɪblɪŋ/"}', null, null),
('00000003-0006-0002-0002-000000000001', '00000002-0000-0000-0006-000000000002', 2, 'flashcard', '{"text": "only child", "subtext": "a child with no brothers or sisters"}', '{"text": "hijo/hija único/a", "phonetic": "/ˈoʊnli tʃaɪld/"}', null, null),
('00000003-0006-0002-0003-000000000001', '00000002-0000-0000-0006-000000000002', 3, 'multiple_choice', '{"text": "¿Cómo dices ''No tengo hermanos'' en inglés?"}', '{"text": "I don''t have any siblings."}', '["I have any siblings.", "I not have siblings.", "I haven''t siblings."]', '{"es": "La negación correcta es ''I don''t have any siblings.'' Usamos ''don''t have'' para la negación de ''have''."}'),
('00000003-0006-0002-0004-000000000001', '00000002-0000-0000-0006-000000000002', 4, 'multiple_choice', '{"text": "''My sister is 10 years old.'' What does this mean?"}', '{"text": "Mi hermana tiene 10 años."}', '["Mi hermana es de 10.", "Mi hermana está 10 años.", "Mis hermanas tienen 10 años."]', '{"es": "En inglés usamos ''is + número + years old'' para expresar la edad. Corresponde a ''tiene X años'' en español."}'),
('00000003-0006-0002-0005-000000000001', '00000002-0000-0000-0006-000000000002', 5, 'fill_blank', '{"text": "I ___ a brother. He is 18 years old."}', '{"text": "have", "accepted": ["have"]}', null, '{"es": "Usamos ''have'' con ''I'' para expresar posesión. ''I have a brother'' = Tengo un hermano."}'),
('00000003-0006-0002-0006-000000000001', '00000002-0000-0000-0006-000000000002', 6, 'fill_blank', '{"text": "My grandmother ___ 80 years old."}', '{"text": "is", "accepted": ["is"]}', null, '{"es": "Para expresar edad en inglés usamos el verbo ''to be''. ''She is 80 years old'' = Ella tiene 80 años."}'),
('00000003-0006-0002-0007-000000000001', '00000002-0000-0000-0006-000000000002', 7, 'translation', '{"text": "Tengo dos hermanos y no tengo hermanas."}', '{"text": "I have two brothers and I don''t have any sisters.", "accepted": ["I have two brothers and no sisters."]}', null, '{"es": "Usamos ''I have'' para lo que tenemos y ''I don''t have'' para lo que no tenemos."}'),
('00000003-0006-0002-0008-000000000001', '00000002-0000-0000-0006-000000000002', 8, 'translation', '{"text": "Soy hijo único. No tengo hermanos."}', '{"text": "I am an only child. I don''t have any siblings.", "accepted": ["I''m an only child. I don''t have siblings."]}', null, '{"es": "''Only child'' significa hijo único. Recuerda usar ''an'' antes de ''only'' porque empieza con vocal."}'),

('00000003-0006-0003-0001-000000000001', '00000002-0000-0000-0006-000000000003', 1, 'flashcard', '{"text": "my", "subtext": "possessive adjective"}', '{"text": "mi / mis", "phonetic": "/maɪ/"}', null, null),
('00000003-0006-0003-0002-000000000001', '00000002-0000-0000-0006-000000000003', 2, 'flashcard', '{"text": "their", "subtext": "possessive adjective (plural)"}', '{"text": "su / sus (de ellos)", "phonetic": "/ðɛr/"}', null, null),
('00000003-0006-0003-0003-000000000001', '00000002-0000-0000-0006-000000000003', 3, 'multiple_choice', '{"text": "María has a dog. ___ dog is small."}', '{"text": "Her"}', '["His", "My", "Our"]', '{"es": "María es mujer, entonces usamos ''Her'' (su de ella). ''His'' sería para un hombre."}'),
('00000003-0006-0003-0004-000000000001', '00000002-0000-0000-0006-000000000003', 4, 'multiple_choice', '{"text": "¿Cómo se dice ''el nombre de mi padre'' en inglés?"}', '{"text": "my father''s name"}', '["the name of my father", "my fathers name", "father my name"]', '{"es": "En inglés usamos apóstrofo-s: ''father''s name''. Aunque ''the name of my father'' es correcto, la forma con apóstrofo es más natural."}'),
('00000003-0006-0003-0005-000000000001', '00000002-0000-0000-0006-000000000003', 5, 'fill_blank', '{"text": "___ mother is a doctor. (Su mamá de Juan)"}', '{"text": "His", "accepted": ["His"]}', null, '{"es": "Juan es hombre, entonces usamos ''His'' para indicar posesión de él. ''His mother'' = su mamá (de él)."}'),
('00000003-0006-0003-0006-000000000001', '00000002-0000-0000-0006-000000000003', 6, 'fill_blank', '{"text": "My sister''s ___ is Carlos. (nombre)"}', '{"text": "husband", "accepted": ["husband", "name"]}', null, '{"es": "''Sister''s husband'' significa el esposo de mi hermana. El apóstrofo-s indica posesión."}'),
('00000003-0006-0003-0007-000000000001', '00000002-0000-0000-0006-000000000003', 7, 'translation', '{"text": "El nombre de mi abuela es Rosa."}', '{"text": "My grandmother''s name is Rosa.", "accepted": ["My grandmother''s name is Rosa."]}', null, '{"es": "Usamos apóstrofo-s para expresar posesión: ''grandmother''s name'' = el nombre de la abuela."}'),
('00000003-0006-0003-0008-000000000001', '00000002-0000-0000-0006-000000000003', 8, 'translation', '{"text": "Su hermano (de ella) es alto y su hermana (de ella) es baja."}', '{"text": "Her brother is tall and her sister is short.", "accepted": ["Her brother is tall and her sister is short."]}', null, '{"es": "Usamos ''her'' para la posesión de ella. Tanto ''her brother'' como ''her sister'' usan el mismo posesivo."}'),

('00000003-0006-0004-0001-000000000001', '00000002-0000-0000-0006-000000000004', 1, 'flashcard', '{"text": "kind", "subtext": "personality adjective"}', '{"text": "amable / bondadoso", "phonetic": "/kaɪnd/"}', null, null),
('00000003-0006-0004-0002-000000000001', '00000002-0000-0000-0006-000000000004', 2, 'flashcard', '{"text": "engineer", "subtext": "profession"}', '{"text": "ingeniero/a", "phonetic": "/ˌɛndʒɪˈnɪər/"}', null, null),
('00000003-0006-0004-0003-000000000001', '00000002-0000-0000-0006-000000000004', 3, 'multiple_choice', '{"text": "''She has brown eyes.'' What does ''brown'' mean here?"}', '{"text": "cafés / marrón"}', '["azules", "verdes", "negros"]', '{"es": "''Brown'' significa marrón o café. ''She has brown eyes'' = Ella tiene ojos cafés."}'),
('00000003-0006-0004-0004-000000000001', '00000002-0000-0000-0006-000000000004', 4, 'multiple_choice', '{"text": "My dad is a doctor. ___ is very smart."}', '{"text": "He"}', '["She", "They", "We"]', '{"es": "''Dad'' (papá) es masculino, entonces usamos el pronombre ''He'' (él) para referirnos a él."}'),
('00000003-0006-0004-0005-000000000001', '00000002-0000-0000-0006-000000000004', 5, 'fill_blank', '{"text": "My mom is a ___. She works at a school. (maestra)"}', '{"text": "teacher", "accepted": ["teacher"]}', null, '{"es": "''Teacher'' significa maestro/a. Usamos ''is a teacher'' para decir la profesión de alguien."}'),
('00000003-0006-0004-0006-000000000001', '00000002-0000-0000-0006-000000000004', 6, 'fill_blank', '{"text": "She has ___ hair and blue eyes. (cabello rubio)"}', '{"text": "blond", "accepted": ["blond", "blonde"]}', null, '{"es": "''Blond'' o ''blonde'' significa rubio. Se usa ''blond'' para hombres y ''blonde'' para mujeres aunque ambas formas son aceptadas."}'),
('00000003-0006-0004-0007-000000000001', '00000002-0000-0000-0006-000000000004', 7, 'translation', '{"text": "Mi mamá es maestra. Ella tiene 45 años y es muy amable."}', '{"text": "My mom is a teacher. She is 45 years old and very kind.", "accepted": ["My mom is a teacher. She is 45 years old and very kind."]}', null, '{"es": "''Kind'' significa amable. Combinamos profesión, edad y personalidad para una descripción completa."}'),
('00000003-0006-0004-0008-000000000001', '00000002-0000-0000-0006-000000000004', 8, 'translation', '{"text": "Mi abuelo tiene 70 años. Él tiene cabello blanco y es muy simpático."}', '{"text": "My grandfather is 70 years old. He has white hair and is very friendly.", "accepted": ["My grandfather is 70 years old. He has white hair and is very friendly."]}', null, '{"es": "''White hair'' es cabello blanco. ''Friendly'' es simpático. Usamos ''He'' para referirnos al abuelo."}');



('00000003-0007-0002-0001-000000000001', '00000002-0000-0000-0007-000000000002', 1, 'flashcard', '{"text": "chicken", "subtext": "meat / protein"}', '{"text": "pollo", "phonetic": "/ˈtʃɪkɪn/"}', null, null),
('00000003-0007-0002-0002-000000000001', '00000002-0000-0000-0007-000000000002', 2, 'flashcard', '{"text": "cheese", "subtext": "dairy product"}', '{"text": "queso", "phonetic": "/tʃiːz/"}', null, null),
('00000003-0007-0002-0003-000000000001', '00000002-0000-0000-0007-000000000002', 3, 'multiple_choice', '{"text": "¿Cómo se dice ''carne de res'' en inglés?"}', '{"text": "beef"}', '["chicken", "fish", "pork"]', '{"es": "''Beef'' es la carne de res. ''Chicken'' es pollo, ''fish'' es pescado y ''pork'' es cerdo."}'),
('00000003-0007-0002-0004-000000000001', '00000002-0000-0000-0007-000000000002', 4, 'multiple_choice', '{"text": "Which food is a dairy product?"}', '{"text": "yogurt"}', '["rice", "chicken", "bread"]', '{"es": "''Yogurt'' es un producto lácteo. ''Rice'' es arroz, ''chicken'' es pollo y ''bread'' es pan."}'),
('00000003-0007-0002-0005-000000000001', '00000002-0000-0000-0007-000000000002', 5, 'fill_blank', '{"text": "I have ___ and toast for breakfast. (huevos)"}', '{"text": "eggs", "accepted": ["eggs"]}', null, '{"es": "''Eggs'' son huevos. Es una proteína popular para el desayuno junto con ''toast'' (pan tostado)."}'),
('00000003-0007-0002-0006-000000000001', '00000002-0000-0000-0007-000000000002', 6, 'fill_blank', '{"text": "She drinks a glass of ___ every morning. (leche)"}', '{"text": "milk", "accepted": ["milk"]}', null, '{"es": "''Milk'' es leche. Es un sustantivo incontable: ''a glass of milk'' = un vaso de leche."}'),
('00000003-0007-0002-0007-000000000001', '00000002-0000-0000-0007-000000000002', 7, 'translation', '{"text": "Como pollo con arroz para el almuerzo."}', '{"text": "I eat chicken and rice for lunch.", "accepted": ["I eat chicken with rice for lunch."]}', null, '{"es": "''Chicken'' es pollo y ''rice'' es arroz. ''Lunch'' es el almuerzo. Ambos son incontables en inglés."}'),
('00000003-0007-0002-0008-000000000001', '00000002-0000-0000-0007-000000000002', 8, 'translation', '{"text": "¿Quieres pan con queso?"}', '{"text": "Would you like some bread and cheese?", "accepted": ["Do you want some bread and cheese?", "Would you like bread and cheese?"]}', null, '{"es": "''Would you like'' es más educado que ''Do you want''. Usamos ''some'' antes de sustantivos incontables."}'),

('00000003-0007-0003-0001-000000000001', '00000002-0000-0000-0007-000000000003', 1, 'flashcard', '{"text": "coffee", "subtext": "hot drink"}', '{"text": "café", "phonetic": "/ˈkɒfi/"}', null, null),
('00000003-0007-0003-0002-000000000001', '00000002-0000-0000-0007-000000000003', 2, 'flashcard', '{"text": "juice", "subtext": "drink"}', '{"text": "jugo / zumo", "phonetic": "/dʒuːs/"}', null, null),
('00000003-0007-0003-0003-000000000001', '00000002-0000-0000-0007-000000000003', 3, 'multiple_choice', '{"text": "¿Cuál es la forma más educada de pedir una bebida?"}', '{"text": "I''d like a water, please."}', '["I want water.", "Give me water.", "Water!"]', '{"es": "''I''d like'' (Me gustaría) es la forma más educada. Siempre añade ''please'' al final para ser cortés."}'),
('00000003-0007-0003-0004-000000000001', '00000002-0000-0000-0007-000000000003', 4, 'multiple_choice', '{"text": "What is the English word for ''té''?"}', '{"text": "tea"}', '["coffee", "soda", "juice"]', '{"es": "''Tea'' significa té. Se pronuncia /tiː/."}'),
('00000003-0007-0003-0005-000000000001', '00000002-0000-0000-0007-000000000003', 5, 'fill_blank', '{"text": "I''d like a cup of ___, please. (café)"}', '{"text": "coffee", "accepted": ["coffee"]}', null, '{"es": "''Coffee'' es café. Decimos ''a cup of coffee'' (una taza de café)."}'),
('00000003-0007-0003-0006-000000000001', '00000002-0000-0000-0007-000000000003', 6, 'fill_blank', '{"text": "Can I have a glass of ___, please? (agua)"}', '{"text": "water", "accepted": ["water"]}', null, '{"es": "''Water'' es agua. ''A glass of water'' = un vaso de agua."}'),
('00000003-0007-0003-0007-000000000001', '00000002-0000-0000-0007-000000000003', 7, 'translation', '{"text": "Me gustaría un jugo de naranja, por favor."}', '{"text": "I''d like an orange juice, please.", "accepted": ["I''d like orange juice, please."]}', null, '{"es": "''I''d like'' = Me gustaría. ''Orange juice'' = jugo de naranja. Recuerda ''please'' al final."}'),
('00000003-0007-0003-0008-000000000001', '00000002-0000-0000-0007-000000000003', 8, 'translation', '{"text": "¿Te gustaría algo de té o café?"}', '{"text": "Would you like some tea or coffee?", "accepted": ["Would you like tea or coffee?"]}', null, '{"es": "''Would you like'' es la forma interrogativa educada para ofrecer algo. ''Some'' se usa para cantidades no especificadas."}'),

('00000003-0007-0004-0001-000000000001', '00000002-0000-0000-0007-000000000004', 1, 'flashcard', '{"text": "waiter", "subtext": "restaurant staff (male)"}', '{"text": "mesero / camarero", "phonetic": "/ˈweɪtər/"}', null, null),
('00000003-0007-0004-0002-000000000001', '00000002-0000-0000-0007-000000000004', 2, 'flashcard', '{"text": "bill", "subtext": "at a restaurant"}', '{"text": "cuenta", "phonetic": "/bɪl/"}', null, null),
('00000003-0007-0004-0003-000000000001', '00000002-0000-0000-0007-000000000004', 3, 'multiple_choice', '{"text": "¿Cómo pides una mesa para dos personas en un restaurante?"}', '{"text": "A table for two, please."}', '["Two tables, please.", "I want two seats.", "Table two, please."]', '{"es": "La frase correcta es ''A table for two, please.'' Significa ''Una mesa para dos personas, por favor.''"}'),
('00000003-0007-0004-0004-000000000001', '00000002-0000-0000-0007-000000000004', 4, 'multiple_choice', '{"text": "How do you ask for the check/bill at a restaurant?"}', '{"text": "Can we have the bill, please?"}', '["Where is the money?", "I need to pay now.", "Bring me the bill!"]', '{"es": "La forma correcta y educada es ''Can we have the bill, please?'' En EE.UU. también se dice ''check'' en lugar de ''bill''."}'),
('00000003-0007-0004-0005-000000000001', '00000002-0000-0000-0007-000000000004', 5, 'fill_blank', '{"text": "Excuse me! Can I see the ___, please? (menú)"}', '{"text": "menu", "accepted": ["menu"]}', null, '{"es": "''Menu'' en inglés se pronuncia /ˈmɛnjuː/. Pedimos ver el menú para elegir nuestra comida."}'),
('00000003-0007-0004-0006-000000000001', '00000002-0000-0000-0007-000000000004', 6, 'fill_blank', '{"text": "I''d like the fish, ___. (por favor)"}', '{"text": "please", "accepted": ["please"]}', null, '{"es": "Siempre añade ''please'' al final de tus pedidos para ser educado en inglés."}'),
('00000003-0007-0004-0007-000000000001', '00000002-0000-0000-0007-000000000004', 7, 'translation', '{"text": "¡Disculpe! ¿Qué recomienda usted?"}', '{"text": "Excuse me! What do you recommend?", "accepted": ["Excuse me! What do you recommend?"]}', null, '{"es": "''Excuse me'' se usa para llamar la atención de alguien. ''What do you recommend?'' pide una recomendación."}'),
('00000003-0007-0004-0008-000000000001', '00000002-0000-0000-0007-000000000004', 8, 'translation', '{"text": "La comida estuvo deliciosa. ¿Nos puede traer la cuenta, por favor?"}', '{"text": "The food was delicious. Can we have the bill, please?", "accepted": ["The meal was delicious. Can we have the bill, please?"]}', null, '{"es": "''Delicious'' es delicioso. ''Can we have the bill'' es la forma de pedir la cuenta. ''Was'' es el pasado de ''is''."}'),

('00000003-0007-0005-0001-000000000001', '00000002-0000-0000-0007-000000000005', 1, 'flashcard', '{"text": "I love it!", "subtext": "expressing strong like"}', '{"text": "¡Me encanta!", "phonetic": "/aɪ lʌv ɪt/"}', null, null),
('00000003-0007-0005-0002-000000000001', '00000002-0000-0000-0007-000000000005', 2, 'flashcard', '{"text": "I hate it.", "subtext": "expressing strong dislike"}', '{"text": "Lo odio. / Lo detesto.", "phonetic": "/aɪ heɪt ɪt/"}', null, null),
('00000003-0007-0005-0003-000000000001', '00000002-0000-0000-0007-000000000005', 3, 'multiple_choice', '{"text": "¿Cómo dices ''No me gusta el brócoli'' en inglés?"}', '{"text": "I don''t like broccoli."}', '["I not like broccoli.", "I dislike of broccoli.", "I no like broccoli."]', '{"es": "La negación correcta es ''I don''t like''. Nunca uses ''I not like'' o ''I no like'' en inglés."}'),
('00000003-0007-0005-0004-000000000001', '00000002-0000-0000-0007-000000000005', 4, 'multiple_choice', '{"text": "''Do you like spicy food?'' — What is the correct answer?"}', '{"text": "Yes, I do. I love it!"}', '["Yes, I like.", "Yes, I am.", "Yes, I does."]', '{"es": "La respuesta correcta usa ''do'' porque la pregunta usa ''do''. ''Yes, I do'' confirma el gusto."}'),
('00000003-0007-0005-0005-000000000001', '00000002-0000-0000-0007-000000000005', 5, 'fill_blank', '{"text": "I ___ pizza! It''s my favorite. (me encanta)"}', '{"text": "love", "accepted": ["love"]}', null, '{"es": "''Love'' expresa un gusto muy intenso, más fuerte que ''like''. ''I love pizza'' = Me encanta la pizza."}'),
('00000003-0007-0005-0006-000000000001', '00000002-0000-0000-0007-000000000005', 6, 'fill_blank', '{"text": "___ you like sushi? (¿Te gusta...?)"}', '{"text": "Do", "accepted": ["Do"]}', null, '{"es": "Para hacer preguntas con ''like'' usamos ''Do'' al inicio: ''Do you like...?'' Es el auxiliar para el presente simple."}'),
('00000003-0007-0005-0007-000000000001', '00000002-0000-0000-0007-000000000005', 7, 'translation', '{"text": "Me encanta el chocolate pero no me gusta la vainilla."}', '{"text": "I love chocolate but I don''t like vanilla.", "accepted": ["I love chocolate but I don''t like vanilla."]}', null, '{"es": "''Love'' para gusto intenso y ''don''t like'' para no gustar. ''But'' conecta los dos ideas contrastantes."}'),
('00000003-0007-0005-0008-000000000001', '00000002-0000-0000-0007-000000000005', 8, 'translation', '{"text": "¿Te gusta la comida italiana? A mí me encanta."}', '{"text": "Do you like Italian food? I love it.", "accepted": ["Do you like Italian food? I love it!"]}', null, '{"es": "''Italian food'' es comida italiana. Usamos ''it'' para referirnos a algo mencionado antes: ''I love it'' = me encanta (la comida italiana)."}');



('00000003-0008-0002-0001-000000000001', '00000002-0000-0000-0008-000000000002', 1, 'flashcard', '{"text": "eye", "subtext": "face part / sense organ"}', '{"text": "ojo", "phonetic": "/aɪ/"}', null, null),
('00000003-0008-0002-0002-000000000001', '00000002-0000-0000-0008-000000000002', 2, 'flashcard', '{"text": "smell", "subtext": "one of the five senses"}', '{"text": "oler / olfato", "phonetic": "/smɛl/"}', null, null),
('00000003-0008-0002-0003-000000000001', '00000002-0000-0000-0008-000000000002', 3, 'multiple_choice', '{"text": "¿Cuál es el plural correcto de ''tooth'' (diente)?"}', '{"text": "teeth"}', '["tooths", "toothes", "tooth"]', '{"es": "''Tooth'' tiene un plural irregular: ''teeth''. Este es uno de los plurales más comunes que debes memorizar."}'),
('00000003-0008-0002-0004-000000000001', '00000002-0000-0000-0008-000000000002', 4, 'multiple_choice', '{"text": "Which verb is used for the sense of taste?"}', '{"text": "taste"}', '["hear", "see", "touch"]', '{"es": "''Taste'' es el verbo para el sentido del gusto. ''Hear'' es escuchar, ''see'' es ver y ''touch'' es tocar."}'),
('00000003-0008-0002-0005-000000000001', '00000002-0000-0000-0008-000000000002', 5, 'fill_blank', '{"text": "I can ___ the coffee from here. (oler)"}', '{"text": "smell", "accepted": ["smell"]}', null, '{"es": "''Smell'' significa oler. ''I can smell the coffee'' = Puedo oler el café desde aquí."}'),
('00000003-0008-0002-0006-000000000001', '00000002-0000-0000-0008-000000000002', 6, 'fill_blank', '{"text": "She has beautiful brown ___. (ojos)"}', '{"text": "eyes", "accepted": ["eyes"]}', null, '{"es": "''Eyes'' son ojos en plural. ''Brown eyes'' = ojos cafés / marrón."}'),
('00000003-0008-0002-0007-000000000001', '00000002-0000-0000-0008-000000000002', 7, 'translation', '{"text": "Ella tiene la nariz pequeña y la boca grande."}', '{"text": "She has a small nose and a big mouth.", "accepted": ["She has a small nose and a big mouth."]}', null, '{"es": "''Nose'' es nariz y ''mouth'' es boca. Usamos ''to have'' para describir características físicas."}'),
('00000003-0008-0002-0008-000000000001', '00000002-0000-0000-0008-000000000002', 8, 'translation', '{"text": "Puedo escuchar música y ver las estrellas."}', '{"text": "I can hear music and see the stars.", "accepted": ["I can hear music and see the stars."]}', null, '{"es": "''Hear'' es escuchar (involuntario) y ''see'' es ver (involuntario). ''Can'' expresa capacidad o percepción sensorial."}'),

('00000003-0008-0003-0001-000000000001', '00000002-0000-0000-0008-000000000003', 1, 'flashcard', '{"text": "headache", "subtext": "health problem"}', '{"text": "dolor de cabeza", "phonetic": "/ˈhɛdeɪk/"}', null, null),
('00000003-0008-0003-0002-000000000001', '00000002-0000-0000-0008-000000000003', 2, 'flashcard', '{"text": "fever", "subtext": "health symptom"}', '{"text": "fiebre", "phonetic": "/ˈfiːvər/"}', null, null),
('00000003-0008-0003-0003-000000000001', '00000002-0000-0000-0008-000000000003', 3, 'multiple_choice', '{"text": "¿Cómo dices ''Tengo un resfriado'' en inglés?"}', '{"text": "I have a cold."}', '["I am cold.", "I have cold.", "I feel a cold."]', '{"es": "''I have a cold'' es la expresión correcta para decir que tienes un resfriado. ''I am cold'' significa que tienes frío (temperatura)."}'),
('00000003-0008-0003-0004-000000000001', '00000002-0000-0000-0008-000000000003', 4, 'multiple_choice', '{"text": "''My stomach hurts.'' What does this mean?"}', '{"text": "Me duele el estómago."}', '["Mi estómago está sucio.", "Tengo hambre.", "Me gusta el estómago."]', '{"es": "''My stomach hurts'' = Me duele el estómago. La estructura ''My + parte del cuerpo + hurts'' expresa dolor."}'),
('00000003-0008-0003-0005-000000000001', '00000002-0000-0000-0008-000000000003', 5, 'fill_blank', '{"text": "I feel very ___. I need to rest. (cansado)"}', '{"text": "tired", "accepted": ["tired"]}', null, '{"es": "''Tired'' significa cansado. ''I feel tired'' = Me siento cansado. Usamos ''feel'' + adjetivo para describir cómo nos sentimos."}'),
('00000003-0008-0003-0006-000000000001', '00000002-0000-0000-0008-000000000003', 6, 'fill_blank', '{"text": "I have a ___ . My temperature is 39°C. (fiebre)"}', '{"text": "fever", "accepted": ["fever"]}', null, '{"es": "''Fever'' significa fiebre. Cuando la temperatura está alta, decimos ''I have a fever''."}'),
('00000003-0008-0003-0007-000000000001', '00000002-0000-0000-0008-000000000003', 7, 'translation', '{"text": "Tengo dolor de cabeza y me siento mareado."}', '{"text": "I have a headache and I feel dizzy.", "accepted": ["I have a headache and I feel dizzy."]}', null, '{"es": "''Headache'' es dolor de cabeza (una sola palabra). ''Dizzy'' significa mareado. ''I feel dizzy'' = Me siento mareado."}'),
('00000003-0008-0003-0008-000000000001', '00000002-0000-0000-0008-000000000003', 8, 'translation', '{"text": "Me duele la garganta y tengo tos."}', '{"text": "My throat hurts and I have a cough.", "accepted": ["My throat hurts and I have a cough."]}', null, '{"es": "''Throat'' es garganta. ''Cough'' es tos. Combinamos dos estructuras diferentes: ''My throat hurts'' y ''I have a cough''."}'),

('00000003-0008-0004-0001-000000000001', '00000002-0000-0000-0008-000000000004', 1, 'flashcard', '{"text": "prescription", "subtext": "medical document"}', '{"text": "receta médica", "phonetic": "/prɪˈskrɪpʃən/"}', null, null),
('00000003-0008-0004-0002-000000000001', '00000002-0000-0000-0008-000000000004', 2, 'flashcard', '{"text": "appointment", "subtext": "scheduled meeting with a doctor"}', '{"text": "cita (médica)", "phonetic": "/əˈpɔɪntmənt/"}', null, null),
('00000003-0008-0004-0003-000000000001', '00000002-0000-0000-0008-000000000004', 3, 'multiple_choice', '{"text": "The doctor says: ''What seems to be the problem?'' What does she want to know?"}', '{"text": "What health problem do you have?"}', '["What is your name?", "What medicine do you take?", "What is the date today?"]', '{"es": "''What seems to be the problem?'' es la manera como el médico pregunta qué problema de salud tienes. Es una pregunta muy común en inglés médico."}'),
('00000003-0008-0004-0004-000000000001', '00000002-0000-0000-0008-000000000004', 4, 'multiple_choice', '{"text": "The doctor says: ''Take this twice a day.'' What does this mean?"}', '{"text": "Tome esto dos veces al día."}', '["Tome esto dos días.", "Tome dos pastillas.", "Tome esto mañana."]', '{"es": "''Twice a day'' significa dos veces al día. ''Once'' = una vez, ''twice'' = dos veces, ''three times'' = tres veces."}'),
('00000003-0008-0004-0005-000000000001', '00000002-0000-0000-0008-000000000004', 5, 'fill_blank', '{"text": "I''d like to make an ___ with the doctor. (cita)"}', '{"text": "appointment", "accepted": ["appointment"]}', null, '{"es": "''Appointment'' es cita. ''To make an appointment'' = hacer una cita. Es la frase para llamar al médico."}'),
('00000003-0008-0004-0006-000000000001', '00000002-0000-0000-0008-000000000004', 6, 'fill_blank', '{"text": "The ___ will give you a prescription. (médico)"}', '{"text": "doctor", "accepted": ["doctor"]}', null, '{"es": "''Doctor'' es el médico. El médico te da una ''prescription'' (receta médica) para comprar tu medicina."}'),
('00000003-0008-0004-0007-000000000001', '00000002-0000-0000-0008-000000000004', 7, 'translation', '{"text": "Me gustaría hacer una cita con el doctor, por favor."}', '{"text": "I''d like to make an appointment with the doctor, please.", "accepted": ["I''d like to make an appointment with the doctor, please."]}', null, '{"es": "''I''d like to make an appointment'' es la frase para pedir una cita. Siempre añade ''please'' para ser educado."}'),
('00000003-0008-0004-0008-000000000001', '00000002-0000-0000-0008-000000000004', 8, 'translation', '{"text": "Tengo fiebre y me duele la garganta desde hace dos días."}', '{"text": "I have a fever and my throat has been hurting for two days.", "accepted": ["I have a fever and my throat hurts. It has been two days.", "I have had a fever and a sore throat for two days."]}', null, '{"es": "''Sore throat'' es otro término común para garganta adolorida. ''For two days'' indica la duración del problema."}');

