INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0003-0003-000000000001', '00000002-0000-0000-0001-000000000003', 3, 'multiple_choice', '{"text": "¿Cómo se llama la letra ''J'' en inglés?"}'::jsonb, '{"text": "Jay /dʒeɪ/"}'::jsonb, '["Jot /dʒɒt/", "Yee /jiː/", "Gee /dʒiː/"]'::jsonb, '{"es": "La letra J en inglés se llama ''Jay'' y se pronuncia /dʒeɪ/. No se pronuncia como la J española. La letra G se llama ''Gee'' /dʒiː/, que suena parecido pero es diferente."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0003-0004-000000000001', '00000002-0000-0000-0001-000000000003', 4, 'multiple_choice', '{"text": "¿Cómo deletreas la palabra HELLO en inglés?"}'::jsonb, '{"text": "H-E-L-L-O"}'::jsonb, '["H-A-L-L-O", "H-E-L-O", "H-I-L-L-O"]'::jsonb, '{"es": "HELLO se deletrea H-E-L-L-O. Tiene doble L. Es una de las primeras palabras que debes aprender a deletrear en inglés."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0003-0005-000000000001', '00000002-0000-0000-0001-000000000003', 5, 'fill_blank', '{"text": "My name is Maria. It''s spelled M-A-R-___-A."}'::jsonb, '{"text": "I", "accepted": ["I", "i"]}'::jsonb, NULL, NULL);
