('00000003-0001-0004-0006-000000000001', '00000002-0000-0000-0001-000000000004', 6, 'fill_blank', '{"text": "___ sells shoes in the shop. (Ella)"}'::jsonb, '{"text": "She", "accepted": ["She", "she"]}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0004-0007-000000000001', '00000002-0000-0000-0001-000000000004', 7, 'multiple_choice', '{"text": "¿Cuál de estas palabras termina con el sonido NG /ŋ/?"}'::jsonb, '{"text": "morning /ˈmɔːrnɪŋ/ — el sufijo -ing termina en NG nasal"}'::jsonb, '["shop /ʃɒp/ — termina en P bilabial", "chair /tʃɛr/ — termina en R inglesa", "fish /fɪʃ/ — termina en SH /ʃ/"]'::jsonb, '{"es": "El sonido NG /ŋ/ aparece en todos los gerundios (-ing) y en palabras como ''morning'', ''ring'', ''long''. Se produce con la parte posterior de la lengua tocando el paladar suave, y el aire sale por la nariz."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
