INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0002-000000000001', '00000001-0000-0000-0000-000000000002', '00000000-0000-0000-0001-000000000001', 1, 'saludos-formales-e-informales', '{"es": "Saludos Formales e Informales", "en": "Formal and Informal Greetings"}'::jsonb, '{"es": "Aprende a saludar en inglés en situaciones formales e informales, desde Hi hasta Good evening.", "en": "Learn to greet in English in formal and informal situations, from Hi to Good evening."}'::jsonb, 'theory_practice', 20, 15, '{"intro": "Los saludos son lo primero que decimos cuando encontramos a alguien. En inglés, hay saludos formales que usamos con personas mayores, jefes, o en situaciones profesionales, y saludos informales que usamos con amigos y familia. Aprender cuándo usar cada uno es tan importante como aprender las palabras mismas.", "sections": [{"type": "explanation", "title": "SALUDOS INFORMALES", "text": "Los saludos informales son los más comunes en el día a día. ''Hi'' es el más frecuente — es amistoso y casual. ''Hey'' es aún más informal y se usa entre amigos cercanos. ''Hello'' es un poco más formal que ''Hi'' pero todavía puede usarse en conversaciones casuales. Después del saludo, normalmente preguntamos cómo está la persona: ''How are you?'', ''How''s it going?'', o ''What''s up?'' (muy informal)."}, {"type": "explanation", "title": "SALUDOS FORMALES POR HORA DEL DÍA", "text": "En situaciones formales, usamos saludos según la hora: ''Good morning'' se usa desde el amanecer hasta el mediodía (12:00 pm). ''Good afternoon'' se usa desde el mediodía hasta las 6:00 pm aproximadamente. ''Good evening'' se usa desde las 6:00 pm hasta la noche. ''Good night'' NO es un saludo — es solo una despedida que se dice al irse a dormir. Este error lo cometen muchos estudiantes."}, {"type": "table", "title": "SALUDOS Y SU USO", "headers": ["Saludo", "Tipo", "Cuándo usarlo", "Respuesta típica"], "rows": [["Hi", "Informal", "Con amigos, familia, conocidos", "Hi! / Hello!"], ["Hey", "Muy informal", "Con amigos íntimos", "Hey! / What''s up!"], ["Hello", "Neutro", "General, teléfono, tiendas", "Hello! / Hi!"], ["Good morning", "Formal", "Hasta el mediodía", "Good morning!"], ["Good afternoon", "Formal", "12pm - 6pm", "Good afternoon!"], ["Good evening", "Formal", "Después de las 6pm", "Good evening!"], ["How are you?", "Saludo-pregunta", "Después del saludo inicial", "Fine, thanks / Great!"]]}, {"type": "examples", "title": "DIÁLOGOS DE EJEMPLO", "items": [{"label": "Informal", "en": "Hey Maria! How''s it going? — Pretty good, thanks! And you?", "es": "¡Hey María! ¿Cómo te va? — ¡Bastante bien, gracias! ¿Y tú?"}, {"label": "Formal", "en": "Good morning, Dr. Smith. How are you? — Very well, thank you.", "es": "Buenos días, Dr. Smith. ¿Cómo está? — Muy bien, gracias."}]}, {"type": "note", "variant": "tip", "text": "Cuando alguien te pregunta ''How are you?'', la respuesta más común no es una descripción detallada de tu vida. Lo típico es decir ''Fine, thanks'' o ''Good, thanks. And you?'' — y luego devolver la pregunta. Es parte de la cortesía social, no una pregunta médica."}]}'::jsonb, true);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0002-000000000002', '00000001-0000-0000-0000-000000000002', '00000000-0000-0000-0001-000000000001', 2, 'presentarte', '{"es": "Presentarte", "en": "Introducing Yourself"}'::jsonb, '{"es": "Aprende a presentarte en inglés: tu nombre, de dónde eres, y cómo decir ''mucho gusto''.", "en": "Learn to introduce yourself in English: your name, where you''re from, and how to say nice to meet you."}'::jsonb, 'theory_practice', 20, 15, '{"intro": "Presentarte a alguien nuevo es una de las situaciones más comunes e importantes en inglés. Ya sea en el trabajo, en la escuela, o en un viaje, necesitarás decir quién eres y de dónde vienes. En esta lección aprenderás las frases esenciales para hacer una buena primera impresión.", "sections": [{"type": "explanation", "title": "CÓMO DECIR TU NOMBRE", "text": "Hay varias formas de decir tu nombre en inglés. La más común y formal es ''My name is [nombre]'' — que es equivalente al español ''Mi nombre es...''. Una versión más casual es ''I''m [nombre]'' que es como decir ''Soy...''. También puedes decir ''I go by [apodo]'' si prefieres que te llamen por un apodo. En inglés americano es muy común ir directo al nombre de pila, incluso en situaciones semi-formales."}, {"type": "explanation", "title": "DE DÓNDE ERES Y MUCHO GUSTO", "text": "Para decir de dónde eres, usa ''I''m from [país/ciudad]'' o ''I come from [país/ciudad]''. Por ejemplo: ''I''m from Mexico'' o ''I come from Colombia''. Para decir ''mucho gusto'' cuando conoces a alguien, las expresiones más comunes son: ''Nice to meet you'' (Mucho gusto/Encantado de conocerte), ''Pleased to meet you'' (más formal), o ''It''s a pleasure'' (Es un placer — más formal aún). La respuesta a ''Nice to meet you'' es típicamente ''Nice to meet you too'' o ''The pleasure is mine''."}, {"type": "table", "title": "FRASES ESENCIALES PARA PRESENTARSE", "headers": ["Frase en inglés", "Traducción", "Nivel de formalidad"], "rows": [["My name is Ana.", "Mi nombre es Ana.", "Formal/Neutro"], ["I''m Carlos.", "Soy Carlos.", "Informal/Neutro"], ["I''m from Mexico.", "Soy de México.", "Neutro"], ["I come from Colombia.", "Vengo de Colombia.", "Neutro/Formal"], ["Nice to meet you.", "Mucho gusto.", "Neutro"], ["Pleased to meet you.", "Encantado/a de conocerle.", "Formal"], ["It''s a pleasure.", "Es un placer.", "Formal"], ["Nice to meet you too.", "Igualmente.", "Neutro"]]}, {"type": "examples", "title": "DIÁLOGOS DE PRESENTACIÓN", "items": [{"label": "Informal", "en": "Hi! I''m Sofia. — Hey, I''m James. Nice to meet you! — Nice to meet you too!", "es": "¡Hola! Soy Sofía. — Hola, soy James. ¡Mucho gusto! — ¡Igualmente!"}, {"label": "Formal", "en": "Good morning. My name is Dr. Rivera. I''m from Argentina. — Pleased to meet you, Dr. Rivera.", "es": "Buenos días. Mi nombre es Dr. Rivera. Soy de Argentina. — Encantado de conocerle, Dr. Rivera."}]}, {"type": "note", "variant": "tip", "text": "En inglés, la contracción ''I''m'' (I am) es muy natural en conversación. Usar ''I am'' suena un poco rígido o enfático. Practica diciendo ''I''m Ana, I''m from Mexico, I''m happy to be here'' hasta que te salga de forma natural."}]}'::jsonb, true);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0002-000000000003', '00000001-0000-0000-0000-000000000002', '00000000-0000-0000-0001-000000000001', 3, 'preguntar-por-alguien', '{"es": "Preguntar por Alguien", "en": "Asking About Someone"}'::jsonb, '{"es": "Aprende a preguntar el nombre, origen y edad de alguien en inglés.", "en": "Learn to ask someone''s name, origin, and age in English."}'::jsonb, 'theory_practice', 20, 15, '{"intro": "Cuando conocemos a alguien, naturalmente queremos saber más sobre esa persona. En inglés, hay preguntas estándar que se usan en estas situaciones. Aprender a hacer estas preguntas correctamente — y a responderlas — te permitirá tener conversaciones reales desde el principio.", "sections": [{"type": "explanation", "title": "PREGUNTAR EL NOMBRE", "text": "La pregunta más básica es ''What''s your name?'' (¿Cuál es tu nombre?). Una variación más formal es ''May I ask your name?'' o ''What is your name?''. En contextos muy informales puedes escuchar ''Who are you?'' pero puede sonar rudo si no se dice con el tono correcto. La respuesta es simplemente ''My name is...'' o ''I''m...''. Si no entendiste el nombre, puedes decir ''Sorry, could you repeat that?'' o ''How do you spell that?''."}, {"type": "explanation", "title": "PREGUNTAR ORIGEN Y EDAD", "text": "Para preguntar de dónde es alguien: ''Where are you from?'' o más formalmente ''Where do you come from?''. La respuesta: ''I''m from [lugar]''. Para la edad, la pregunta es ''How old are you?'' y la respuesta es ''I''m [número] years old'' — nota que en inglés se dice el número primero y luego ''years old''. Por ejemplo: ''I''m twenty-five years old'' o en conversación casual solo ''I''m twenty-five''. Preguntar la edad puede ser delicado culturalmente — en muchos contextos anglosajones es considerado personal, especialmente a adultos."}, {"type": "table", "title": "PREGUNTAS Y RESPUESTAS BÁSICAS", "headers": ["Pregunta", "Respuesta ejemplo", "Notas"], "rows": [["What''s your name?", "My name is Sofia. / I''m Sofia.", "La más común"], ["Where are you from?", "I''m from Mexico. / I''m Mexican.", "''I''m Mexican'' = gentilicio"], ["Where do you live?", "I live in New York.", "Lugar de residencia actual"], ["How old are you?", "I''m twenty-eight years old.", "Puede ser personal"], ["What do you do?", "I''m a teacher. / I''m a student.", "Pregunta sobre profesión"]]}, {"type": "examples", "title": "MINI CONVERSACIONES", "items": [{"label": "Conociendo a alguien", "en": "What''s your name? — I''m Pedro. Where are you from, Pedro? — I''m from Spain. And how old are you? — I''m thirty.", "es": "¿Cómo te llamas? — Soy Pedro. ¿De dónde eres, Pedro? — Soy de España. ¿Y cuántos años tienes? — Tengo treinta."}, {"label": "Profesión", "en": "What do you do? — I''m a doctor. I work at a hospital.", "es": "¿A qué te dedicas? — Soy médico. Trabajo en un hospital."}]}, {"type": "note", "variant": "tip", "text": "En inglés, ''I''m Mexican'' (con gentilicio) y ''I''m from Mexico'' (con el país) son intercambiables. Los gentilicios en inglés siempre se escriben con mayúscula: Mexican, Colombian, Spanish, Brazilian. No son como en español donde se escriben en minúscula."}]}'::jsonb, true);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0002-000000000004', '00000001-0000-0000-0000-000000000002', '00000000-0000-0000-0001-000000000001', 4, 'las-despedidas', '{"es": "Las Despedidas", "en": "Goodbyes and Farewells"}'::jsonb, '{"es": "Aprende a despedirte en inglés: Goodbye, See you, Take care, Have a good day y más.", "en": "Learn to say goodbye in English: Goodbye, See you, Take care, Have a good day, and more."}'::jsonb, 'theory_practice', 20, 15, '{"intro": "Saber despedirse correctamente es tan importante como saber saludar. En inglés hay muchas formas de decir adiós, desde las más formales hasta las más casuales. Además, existen frases especiales para desearle algo bueno a la otra persona al despedirse, lo cual es muy común en la cultura anglosajona.", "sections": [{"type": "explanation", "title": "DESPEDIDAS BÁSICAS", "text": "La despedida más conocida es ''Goodbye'' — es formal y completa. En conversación casual se acorta a ''Bye'' o ''Bye bye'' (este último suena infantil entre adultos, mejor usarlo con niños). ''See you'' significa ''hasta la vista'' o ''nos vemos'' y es muy común. Puedes añadir cuándo: ''See you tomorrow'' (hasta mañana), ''See you later'' (hasta luego), ''See you next week'' (hasta la próxima semana). ''Take care'' significa ''cuídate'' y es una despedida cariñosa muy frecuente."}, {"type": "explanation", "title": "DESPEDIDAS CON BUENOS DESEOS", "text": "Es muy común en inglés desearle algo bueno a alguien al despedirse. Las frases más usadas son: ''Have a good day!'' (¡Que tengas un buen día!), ''Have a great weekend!'' (¡Que tengas un excelente fin de semana!), ''Have fun!'' (¡Que te diviertas!), ''Good luck!'' (¡Buena suerte!), y ''Take care!'' (¡Cuídate!). La respuesta típica es ''You too!'' (¡Tú también!) o ''Thanks, you too!''."}, {"type": "table", "title": "DESPEDIDAS EN INGLÉS", "headers": ["Despedida", "Significado", "Formalidad"], "rows": [["Goodbye", "Adiós", "Formal/Neutro"], ["Bye / Bye bye", "Chao / Adiós", "Informal"], ["See you", "Hasta la vista / Nos vemos", "Informal"], ["See you later", "Hasta luego", "Informal"], ["See you tomorrow", "Hasta mañana", "Informal"], ["Take care", "Cuídate", "Neutro/Cariñoso"], ["Have a good day!", "¡Que tengas un buen día!", "Neutro"], ["Good night", "Buenas noches (al dormir)", "Neutro"], ["Farewell", "Que te vaya bien / Adiós", "Muy formal"]]}, {"type": "examples", "title": "EJEMPLOS DE DESPEDIDAS", "items": [{"label": "Al salir del trabajo", "en": "Bye everyone! Have a great evening! — Thanks, you too! See you tomorrow!", "es": "¡Adiós a todos! ¡Que tengan una buena tarde! — ¡Gracias, igualmente! ¡Hasta mañana!"}, {"label": "Al terminar una llamada", "en": "Okay, I have to go now. Take care! — You too! Bye!", "es": "Bueno, tengo que irme. ¡Cuídate! — ¡Igualmente! ¡Adiós!"}]}, {"type": "note", "variant": "tip", "text": "Recuerda: ''Good night'' NO es un saludo para las noches, es solo una despedida. Si llegas a una fiesta a las 9pm, dices ''Good evening'' para saludar. ''Good night'' solo se dice al final de la noche cuando alguien se va o se va a dormir."}]}'::jsonb, true);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0002-000000000005', '00000001-0000-0000-0000-000000000002', '00000000-0000-0000-0001-000000000001', 5, 'frases-de-cortesia', '{"es": "Frases de Cortesía", "en": "Polite Phrases"}'::jsonb, '{"es": "Aprende las frases de cortesía esenciales: Please, Thank you, You''re welcome, Sorry, Excuse me.", "en": "Learn essential polite phrases: Please, Thank you, You''re welcome, Sorry, Excuse me."}'::jsonb, 'theory_practice', 20, 15, '{"intro": "Las frases de cortesía son el lubricante social de cualquier idioma. En inglés, usar ''please'', ''thank you'' y ''excuse me'' es extremadamente importante y marca la diferencia entre sonar educado o grosero. En la cultura anglosajona, especialmente en países como Estados Unidos, Canadá y el Reino Unido, estas frases se usan con mucha frecuencia — más que en muchas culturas hispanohablantes.", "sections": [{"type": "explanation", "title": "PLEASE Y THANK YOU", "text": "''Please'' se añade al final o inicio de una petición para hacerla educada: ''Could you help me, please?'' o ''Please sit down.''. ''Thank you'' es la forma estándar de dar las gracias. Versiones más enfáticas: ''Thank you very much'' o ''Thanks a lot''. La versión informal es simplemente ''Thanks''. Una variación formal es ''I appreciate it'' (Te lo agradezco). En inglés, es muy común dar las gracias incluso por cosas pequeñas, como cuando el mesero trae tu comida o alguien te abre la puerta."}, {"type": "explanation", "title": "YOU''RE WELCOME, SORRY Y EXCUSE ME", "text": "La respuesta a ''Thank you'' más común es ''You''re welcome'' (De nada). Otras opciones: ''No problem'' (Sin problema — informal), ''Don''t mention it'' (No hay de qué — formal), ''My pleasure'' (Con mucho gusto). Para disculparse: ''Sorry'' o ''I''m sorry'' para disculpas simples; ''I''m so sorry'' para situaciones más serias; ''I apologize'' es formal. ''Excuse me'' se usa para llamar la atención de alguien, para pasar entre personas, o antes de hacer una pregunta. ''Pardon me'' es más formal y tiene el mismo uso."}, {"type": "table", "title": "FRASES DE CORTESÍA Y SUS USOS", "headers": ["Frase", "Significado", "Cuándo usarla"], "rows": [["Please", "Por favor", "Al hacer peticiones"], ["Thank you / Thanks", "Gracias", "Para agradecer algo"], ["Thank you very much", "Muchas gracias", "Para agradecer enfáticamente"], ["You''re welcome", "De nada", "Respuesta a ''thank you''"], ["No problem", "Sin problema", "Respuesta informal a ''thank you''"], ["Sorry / I''m sorry", "Lo siento / Perdón", "Para disculparse"], ["Excuse me", "Disculpe / Con permiso", "Para llamar atención o pasar"], ["Pardon me", "Perdone usted", "Formal, igual que excuse me"]]}, {"type": "examples", "title": "FRASES EN CONTEXTO", "items": [{"label": "En un restaurante", "en": "Could I have the menu, please? — Of course! Here you go. — Thank you! — You''re welcome!", "es": "¿Me podría traer el menú, por favor? — ¡Claro! Aquí tiene. — ¡Gracias! — ¡De nada!"}, {"label": "Pasando entre personas", "en": "Excuse me, could I get through? — Of course, go ahead!", "es": "Con permiso, ¿puedo pasar? — ¡Claro, adelante!"}, {"label": "Disculpándose", "en": "Oh, I''m sorry! I didn''t see you there. — No problem, don''t worry!", "es": "¡Oh, lo siento! No te vi. — ¡Sin problema, no te preocupes!"}]}, {"type": "note", "variant": "tip", "text": "Una diferencia cultural importante: en inglés es completamente normal y esperado decir ''thank you'' cuando alguien hace su trabajo (camarero, cajero, conductor de autobús). No es condescendiente — es cortesía básica. También es muy común responder con ''have a good day!'' después de un intercambio breve con un desconocido."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0002-0001-0001-000000000001', '00000002-0000-0000-0002-000000000001', 1, 'flashcard', '{"text": "Good morning", "subtext": "Saludo formal para la mañana"}'::jsonb, '{"text": "Buenos días", "phonetic": "/ɡʊd ˈmɔːrnɪŋ/"}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0002-0001-0002-000000000001', '00000002-0000-0000-0002-000000000001', 2, 'flashcard', '{"text": "How''s it going?", "subtext": "Saludo informal — equivalente a ¿Cómo te va?"}'::jsonb, '{"text": "¿Cómo te va? / ¿Qué tal?", "phonetic": "/haʊz ɪt ˈɡoʊɪŋ/"}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0002-0001-0003-000000000001', '00000002-0000-0000-0002-000000000001', 3, 'multiple_choice', '{"text": "Son las 8:00 pm. ¿Cuál es el saludo formal correcto?"}'::jsonb, '{"text": "Good evening"}'::jsonb, '["Good morning", "Good afternoon", "Good night"]'::jsonb, '{"es": "''Good evening'' se usa desde las 6pm aproximadamente. ''Good morning'' es hasta el mediodía, ''Good afternoon'' es de 12pm a 6pm. ''Good night'' NO es un saludo — es una despedida para ir a dormir."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0002-0001-0004-000000000001', '00000002-0000-0000-0002-000000000001', 4, 'multiple_choice', '{"text": "¿Cuál es la respuesta más apropiada a ''How are you?'' en una conversación casual?"}'::jsonb, '{"text": "Fine, thanks. And you?"}'::jsonb, '["I am experiencing moderate fatigue and slight stress from work.", "I don''t know.", "Good night!"]'::jsonb, '{"es": "La respuesta social correcta a ''How are you?'' es breve y positiva: ''Fine, thanks'' o ''Good, thanks'', y luego devuelves la pregunta con ''And you?''. No se espera una descripción detallada de tu estado de ánimo."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0002-0001-0005-000000000001', '00000002-0000-0000-0002-000000000001', 5, 'fill_blank', '{"text": "___ afternoon! How are you today? (saludo formal de tarde)"}'::jsonb, '{"text": "Good", "accepted": ["Good", "good"]}'::jsonb, NULL, NULL);
