('00000003-0002-0001-0006-000000000001', '00000002-0000-0000-0002-000000000001', 6, 'fill_blank', '{"text": "Hi Maria! ___ it going? (saludo informal)"}'::jsonb, '{"text": "How''s", "accepted": ["How''s", "How is"]}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
