INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0002-0002-0001-000000000001', '00000002-0000-0000-0002-000000000002', 1, 'flashcard', '{"text": "Nice to meet you", "subtext": "Expresión al conocer a alguien por primera vez"}'::jsonb, '{"text": "Mucho gusto / Encantado de conocerte", "phonetic": "/naɪs tə miːt juː/"}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0002-0002-0002-000000000001', '00000002-0000-0000-0002-000000000002', 2, 'flashcard', '{"text": "I''m from Brazil.", "subtext": "Cómo decir tu país de origen"}'::jsonb, '{"text": "Soy de Brasil.", "phonetic": "/aɪm frəm brəˈzɪl/"}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0002-0002-0003-000000000001', '00000002-0000-0000-0002-000000000002', 3, 'multiple_choice', '{"text": "¿Cuál es la respuesta correcta a ''Nice to meet you''?"}'::jsonb, '{"text": "Nice to meet you too!"}'::jsonb, '["Nice to meet you again!", "Good morning!", "I''m fine, thanks!"]'::jsonb, '{"es": "Cuando alguien dice ''Nice to meet you'', la respuesta natural es ''Nice to meet you too!'' o ''The pleasure is mine''. Es una respuesta de espejo — devuelves el mismo sentimiento."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0002-0002-0004-000000000001', '00000002-0000-0000-0002-000000000002', 4, 'multiple_choice', '{"text": "¿Cuál es la forma más informal de presentarse?"}'::jsonb, '{"text": "I''m Sofia."}'::jsonb, '["My name is Sofia.", "I am Sofia, pleased to meet you.", "Allow me to introduce myself: Sofia."]'::jsonb, '{"es": "''I''m Sofia'' es la forma más casual e informal. ''My name is Sofia'' es más formal o neutro. Las otras opciones son muy formales para conversación casual."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0002-0002-0005-000000000001', '00000002-0000-0000-0002-000000000002', 5, 'fill_blank', '{"text": "Hi! ___ name is Carlos and I''m from Chile. (mi)"}'::jsonb, '{"text": "my", "accepted": ["my", "My"]}'::jsonb, NULL, NULL);
