('00000003-0003-0001-0003-000000000001', '00000002-0000-0000-0003-000000000001', 3, 'multiple_choice', '{"text": "¿Cómo se dice ''15'' en inglés?"}'::jsonb, '{"text": "fifteen"}'::jsonb, '["fifty","fiveteen","five"]'::jsonb, '{"es": "15 se dice ''fifteen''. Cuidado con ''fifty'' que significa 50, no 15."}'::jsonb),
('00000003-0003-0001-0004-000000000001', '00000002-0000-0000-0003-000000000001', 4, 'multiple_choice', '{"text": "¿Cuánto es ''eleven'' en español?"}'::jsonb, '{"text": "once"}'::jsonb, '["doce","diez","trece"]'::jsonb, '{"es": "''Eleven'' significa once (11). No confundir con ''twelve'' (12) o ''ten'' (10)."}'::jsonb),
